def is_select_only(sql: str) -> bool:
    try:
        trees = sqlglot.parse(sql, read="postgres")
    except sqlglot.errors.SqlglotError:
        return False
    return len(trees) == 1 and isinstance(trees[0], exp.Select)

class RefundArgs(BaseModel):
    order_id: str = Field(pattern=r"^ORD-\d{6}$")
    amount: float = Field(gt=0, le=500)

def generate_valid(prompt, max_attempts=3):
    hint = ""
    for _ in range(max_attempts):
        text = llm(prompt + hint)
        try:
            return Answer.model_validate_json(text)
        except ValidationError as e:
            hint = f"\nPrevious output was invalid: {e}"
    raise RuntimeError("no valid output")

def process_payment(key, amount):
    if key in RESULTS:
        return RESULTS[key]
    result = charge(amount)
    RESULTS[key] = result
    return result

def call_tool(name, args):
    if name not in ALLOWED:
        raise PermissionError(f"tool {name!r} is not allowed")
    return TOOLS[name](**args)
